package com.geflipper;

import com.geflipper.PriceData.Average;
import com.geflipper.PriceData.ItemInfo;
import com.geflipper.PriceData.Latest;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Ranks items by what one buy-limit window of flipping them earns. A flip
 * buys with an offer at the instant-sell price and sells with an offer at the
 * instant-buy price, paying GE tax on the sale.
 */
public final class FlipFinder
{
	public enum Members
	{
		ALL("All items"), F2P("Free-to-play only"), MEMBERS("Members only");

		private final String label;

		Members(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	public enum Sort
	{
		PROFIT("Profit per limit"), ROI("ROI"), MARGIN("Margin"), VOLUME("24h volume");

		private final String label;

		Sort(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** What the player is looking for. */
	public static final class Filter
	{
		/** Cash to spend; 0 means rank by buy limit alone. */
		public long cash;
		/** Minimum items traded over the last day. */
		public long minVolume = 1000;
		/** Skip flips whose older price is older than this. */
		public long maxAgeSeconds = 3600;
		public long minMargin = 1;
		public Members members = Members.ALL;
		public String search = "";
		public Sort sort = Sort.PROFIT;
	}

	/** One flip opportunity. */
	public static final class Flip
	{
		public final ItemInfo item;
		public final long buy;
		public final long sell;
		public final long tax;
		public final long margin;
		public final double roi;
		public final long quantity;
		public final long profit;
		public final long ageSeconds;
		public final long volume;

		Flip(ItemInfo item, long buy, long sell, long quantity, long ageSeconds, long volume)
		{
			this.item = item;
			this.buy = buy;
			this.sell = sell;
			this.tax = GeTax.perItem(sell, item.id);
			this.margin = sell - tax - buy;
			this.roi = (double) margin / buy;
			this.quantity = quantity;
			this.profit = margin * quantity;
			this.ageSeconds = ageSeconds;
			this.volume = volume;
		}
	}

	private FlipFinder()
	{
	}

	/** How many one limit window lets you buy with {@code cash} (0 = ignore cash). */
	static long quantity(Integer limit, long buy, long cash)
	{
		long affordable = cash > 0 ? cash / buy : Long.MAX_VALUE;
		long max = limit != null ? limit : Long.MAX_VALUE;
		long q = Math.min(affordable, max);
		return q == Long.MAX_VALUE ? 0 : q;
	}

	/** The flip for one item, or null if it has no two-sided price. */
	public static Flip flip(ItemInfo item, Latest price, Average day, long cash, long now)
	{
		if (price == null || price.high == null || price.low == null || price.high <= 0 || price.low <= 0)
		{
			return null;
		}
		long oldest = Math.min(price.highTime == null ? 0 : price.highTime, price.lowTime == null ? 0 : price.lowTime);
		long age = oldest > 0 ? Math.max(0, now - oldest) : Long.MAX_VALUE;
		long volume = day == null ? 0 : day.volume();
		return new Flip(item, price.low, price.high, quantity(item.limit, price.low, cash), age, volume);
	}

	public static List<Flip> rank(
		Collection<ItemInfo> items,
		Map<Integer, Latest> latest,
		Map<Integer, Average> day,
		Filter filter,
		long now)
	{
		String search = filter.search == null ? "" : filter.search.trim().toLowerCase(Locale.ROOT);
		List<Flip> out = new ArrayList<>();
		for (ItemInfo item : items)
		{
			if (filter.members == Members.F2P && item.members || filter.members == Members.MEMBERS && !item.members)
			{
				continue;
			}
			if (!search.isEmpty() && !item.name.toLowerCase(Locale.ROOT).contains(search))
			{
				continue;
			}
			Flip f = flip(item, latest.get(item.id), day.get(item.id), filter.cash, now);
			if (f == null || f.volume < filter.minVolume || f.margin < filter.minMargin || f.ageSeconds > filter.maxAgeSeconds)
			{
				continue;
			}
			if (filter.cash > 0 && f.quantity < 1)
			{
				continue;
			}
			out.add(f);
		}
		out.sort(comparator(filter.sort).thenComparing(f -> f.item.name));
		return out;
	}

	private static Comparator<Flip> comparator(Sort sort)
	{
		switch (sort)
		{
			case ROI:
				return Comparator.comparingDouble((Flip f) -> f.roi).reversed();
			case MARGIN:
				return Comparator.comparingLong((Flip f) -> f.margin).reversed();
			case VOLUME:
				return Comparator.comparingLong((Flip f) -> f.volume).reversed();
			case PROFIT:
			default:
				return Comparator.comparingLong((Flip f) -> f.profit).reversed();
		}
	}
}

package com.geflipper;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The player's own flips. Buys become lots; each sale is matched against the
 * oldest lots of the same item, and the difference, after GE tax, is profit.
 * Items sold that were never seen being bought (bought before the plugin was
 * installed, or looted) are left out of profit rather than guessed at.
 *
 * Plain fields, so Gson can store it in the RuneScape profile config. The
 * client thread records trades while the panel reads, so every method that
 * touches the lists is synchronized and hands out copies.
 */
public final class FlipLedger
{
	/** How many completed sales to keep. */
	static final int MAX_SALES = 500;

	/** Items bought and not yet sold. */
	public static final class Lot
	{
		public int itemId;
		public long quantity;
		/** Total gp paid for {@code quantity} items. */
		public long cost;
		public long time;
	}

	/** A sale matched against earlier buys. */
	public static final class Sale
	{
		public int itemId;
		public long quantity;
		public long cost;
		/** gp received before tax. */
		public long revenue;
		public long tax;
		public long profit;
		public long time;
	}

	/** Everything held of one item. */
	public static final class Holding
	{
		public final int itemId;
		public final long quantity;
		public final long cost;

		Holding(int itemId, long quantity, long cost)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.cost = cost;
		}

		public long averageCost()
		{
			return quantity == 0 ? 0 : cost / quantity;
		}
	}

	public List<Lot> lots = new ArrayList<>();
	/** Newest last. */
	public List<Sale> sales = new ArrayList<>();

	public synchronized void recordBuy(int itemId, long quantity, long gp, long time)
	{
		if (quantity <= 0)
		{
			return;
		}
		Lot lot = new Lot();
		lot.itemId = itemId;
		lot.quantity = quantity;
		lot.cost = gp;
		lot.time = time;
		lots.add(lot);
	}

	/**
	 * Record a sale of {@code quantity} items for {@code gp} before tax.
	 *
	 * @return the matched sale, or null if none of these items were bought
	 * while the plugin was watching
	 */
	public synchronized Sale recordSell(int itemId, long quantity, long gp, long time)
	{
		if (quantity <= 0)
		{
			return null;
		}
		long matched = 0;
		long cost = 0;
		for (Iterator<Lot> it = lots.iterator(); it.hasNext() && matched < quantity; )
		{
			Lot lot = it.next();
			if (lot.itemId != itemId)
			{
				continue;
			}
			long take = Math.min(lot.quantity, quantity - matched);
			long part = take == lot.quantity ? lot.cost : Math.round((double) lot.cost * take / lot.quantity);
			cost += part;
			matched += take;
			lot.quantity -= take;
			lot.cost -= part;
			if (lot.quantity == 0)
			{
				it.remove();
			}
		}
		if (matched == 0)
		{
			return null;
		}

		// The GE taxes each item on its own sale price.
		long unitPrice = gp / quantity;
		long revenue = matched == quantity ? gp : Math.round((double) gp * matched / quantity);
		Sale sale = new Sale();
		sale.itemId = itemId;
		sale.quantity = matched;
		sale.cost = cost;
		sale.revenue = revenue;
		sale.tax = GeTax.perItem(unitPrice, itemId) * matched;
		sale.profit = revenue - sale.tax - cost;
		sale.time = time;
		sales.add(sale);
		while (sales.size() > MAX_SALES)
		{
			sales.remove(0);
		}
		return sale;
	}

	/** Total profit from sales at or after {@code since} (unix seconds). */
	public synchronized long profitSince(long since)
	{
		long total = 0;
		for (Sale s : sales)
		{
			if (s.time >= since)
			{
				total += s.profit;
			}
		}
		return total;
	}

	public synchronized int salesSince(long since)
	{
		int n = 0;
		for (Sale s : sales)
		{
			if (s.time >= since)
			{
				n++;
			}
		}
		return n;
	}

	/** Unsold items, grouped by item, in the order they were first bought. */
	public synchronized List<Holding> holdings()
	{
		Map<Integer, long[]> byItem = new LinkedHashMap<>();
		for (Lot lot : lots)
		{
			long[] acc = byItem.computeIfAbsent(lot.itemId, k -> new long[2]);
			acc[0] += lot.quantity;
			acc[1] += lot.cost;
		}
		List<Holding> out = new ArrayList<>();
		for (Map.Entry<Integer, long[]> e : byItem.entrySet())
		{
			out.add(new Holding(e.getKey(), e.getValue()[0], e.getValue()[1]));
		}
		return out;
	}

	/** The latest {@code n} sales, newest first. */
	public synchronized List<Sale> recentSales(int n)
	{
		List<Sale> out = new ArrayList<>();
		for (int i = sales.size() - 1; i >= 0 && out.size() < n; i--)
		{
			out.add(sales.get(i));
		}
		return out;
	}

	/** Forget an item's unsold lots, e.g. after using them instead of selling. */
	public synchronized void dropHolding(int itemId)
	{
		lots.removeIf(l -> l.itemId == itemId);
	}

	public synchronized void clear()
	{
		lots.clear();
		sales.clear();
	}
}

package com.geflipper;

import java.text.NumberFormat;
import java.util.Locale;

/** Number and time formatting in the style players read on the GE. */
public final class Format
{
	private Format()
	{
	}

	/** Compact gp: 950 / 12,400 / 125K / 4.56M / 1.45B. */
	public static String gp(long n)
	{
		String sign = n < 0 ? "-" : "";
		long a = Math.abs(n);
		if (a < 100_000)
		{
			return sign + NumberFormat.getIntegerInstance(Locale.UK).format(a);
		}
		if (a < 999_500)
		{
			return sign + Math.round(a / 1_000.0) + "K";
		}
		if (a < 999_500_000)
		{
			return sign + trim(a / 1_000_000.0, a < 100_000_000 ? 2 : 1) + "M";
		}
		return sign + trim(a / 1_000_000_000.0, 2) + "B";
	}

	/** Compact gp with a leading + for gains. */
	public static String signed(long n)
	{
		return (n > 0 ? "+" : "") + gp(n);
	}

	/** Exact gp with thousands separators. */
	public static String exact(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.UK).format(n);
	}

	public static String percent(double x)
	{
		double v = x * 100;
		return String.format(Locale.UK, Math.abs(v) < 10 ? "%.2f%%" : "%.1f%%", v);
	}

	public static String ago(long seconds)
	{
		if (seconds == Long.MAX_VALUE)
		{
			return "never";
		}
		if (seconds < 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return seconds / 60 + "m ago";
		}
		if (seconds < 86400)
		{
			return seconds / 3600 + "h ago";
		}
		return seconds / 86400 + "d ago";
	}

	/**
	 * Parse an amount the way players type it: "10m", "250k", "1.5b",
	 * "12,000". Returns 0 for anything unreadable.
	 */
	public static long parseGp(String text)
	{
		if (text == null)
		{
			return 0;
		}
		String t = text.trim().toLowerCase(Locale.ROOT).replaceAll("[,_ ]", "");
		if (!t.matches("\\d+(\\.\\d+)?[kmb]?"))
		{
			return 0;
		}
		double mult = 1;
		char last = t.charAt(t.length() - 1);
		if (last == 'k' || last == 'm' || last == 'b')
		{
			mult = last == 'k' ? 1e3 : last == 'm' ? 1e6 : 1e9;
			t = t.substring(0, t.length() - 1);
		}
		return Math.round(Double.parseDouble(t) * mult);
	}

	private static String trim(double x, int digits)
	{
		String s = String.format(Locale.UK, "%." + digits + "f", x);
		if (s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s;
	}
}

package com.geflipper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(GeFlipperConfig.GROUP)
public interface GeFlipperConfig extends Config
{
	String GROUP = "geflipper";

	@ConfigItem(
		keyName = "cashStack",
		name = "Cash stack",
		description = "How much you have to flip with, e.g. 10m or 250k. Leave blank to rank by buy limit alone.",
		position = 1
	)
	default String cashStack()
	{
		return "";
	}

	@ConfigItem(
		keyName = "minVolume",
		name = "Min 24h volume",
		description = "Hide items that traded fewer than this many times in the last day. Thin items rarely fill.",
		position = 2
	)
	@Range(min = 0)
	default int minVolume()
	{
		return 1000;
	}

	@ConfigItem(
		keyName = "maxAgeMinutes",
		name = "Max price age (minutes)",
		description = "Hide flips whose buy or sell price is older than this.",
		position = 3
	)
	@Range(min = 1)
	default int maxAgeMinutes()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "members",
		name = "Items",
		description = "Which items to include.",
		position = 4
	)
	default FlipFinder.Members members()
	{
		return FlipFinder.Members.ALL;
	}

	@ConfigItem(
		keyName = "sort",
		name = "Sort by",
		description = "How to rank flips.",
		position = 5
	)
	default FlipFinder.Sort sort()
	{
		return FlipFinder.Sort.PROFIT;
	}

	@ConfigItem(
		keyName = "rows",
		name = "Flips shown",
		description = "How many flips to list in the panel.",
		position = 6
	)
	@Range(min = 5, max = 200)
	default int rows()
	{
		return 40;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Profit in chat",
		description = "Post a chat message with the profit when one of your flips sells.",
		position = 7
	)
	default boolean chatMessages()
	{
		return true;
	}
}

package com.geflipper;

import com.geflipper.PriceData.Latest;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;
import net.runelite.client.util.LinkBrowser;

/** The sidebar: live flips on one tab, the player's own flips on the other. */
class GeFlipperPanel extends PluginPanel
{
	private static final Color GAIN = ColorScheme.GRAND_EXCHANGE_PRICE;
	private static final Color LOSS = ColorScheme.PROGRESS_ERROR_COLOR;
	private static final Color STALE = ColorScheme.PROGRESS_INPROGRESS_COLOR;
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	private static final int RECENT_SALES = 30;

	private final GeFlipperPlugin plugin;
	private final GeFlipperConfig config;
	private final ItemManager itemManager;

	private final JLabel status = new JLabel("Loading prices…");
	private final IconTextField search = new IconTextField();
	private final JLabel filterSummary = new JLabel();
	private final JPanel flipList = new JPanel(new GridLayout(0, 1, 0, 4));
	private final JPanel ledgerView = new JPanel();
	private final Timer clock;

	GeFlipperPanel(GeFlipperPlugin plugin, GeFlipperConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;

		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setLayout(new BorderLayout());

		// Header: title, freshness, refresh.
		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(false);
		JLabel title = new JLabel("GE Flipper");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(MUTED);
		JPanel titles = new JPanel(new GridLayout(2, 1));
		titles.setOpaque(false);
		titles.add(title);
		titles.add(status);
		JButton refresh = new JButton("Refresh");
		refresh.setFont(FontManager.getRunescapeSmallFont());
		refresh.setFocusPainted(false);
		refresh.setToolTipText("Fetch the latest prices now");
		refresh.addActionListener(e -> plugin.refreshNow());
		header.add(titles, BorderLayout.CENTER);
		header.add(refresh, BorderLayout.EAST);

		// Tabs.
		JPanel display = new JPanel(new BorderLayout());
		display.setOpaque(false);
		MaterialTabGroup tabs = new MaterialTabGroup(display);
		tabs.setLayout(new GridLayout(1, 0, 7, 7));
		tabs.setBorder(new EmptyBorder(10, 0, 10, 0));
		MaterialTab flipsTab = new MaterialTab("Flips", tabs, buildFlipsView());
		MaterialTab ledgerTab = new MaterialTab("My flips", tabs, buildLedgerView());
		tabs.addTab(flipsTab);
		tabs.addTab(ledgerTab);
		tabs.select(flipsTab);

		JPanel north = new JPanel();
		north.setOpaque(false);
		north.setLayout(new BoxLayout(north, BoxLayout.Y_AXIS));
		header.setAlignmentX(LEFT_ALIGNMENT);
		tabs.setAlignmentX(LEFT_ALIGNMENT);
		north.add(header);
		north.add(tabs);

		add(north, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);

		clock = new Timer(5000, e -> updateStatus());
		clock.start();
		rebuildFlips();
		rebuildLedger();
	}

	void dispose()
	{
		clock.stop();
	}

	void pricesUpdated()
	{
		updateStatus();
		rebuildFlips();
		rebuildLedger();
	}

	void ledgerUpdated()
	{
		rebuildLedger();
	}

	// ------------------------------------------------------------------ status

	private void updateStatus()
	{
		PriceService prices = plugin.getPrices();
		long at = prices.getUpdatedAt();
		if (at == 0)
		{
			status.setText(prices.getError() != null ? prices.getError() : "Loading prices…");
			status.setForeground(prices.getError() != null ? LOSS : MUTED);
			return;
		}
		long secs = (System.currentTimeMillis() - at) / 1000;
		String when = secs < 10 ? "just now" : secs < 60 ? secs + "s ago" : Format.ago(secs);
		status.setText(prices.getError() != null ? "Refresh failed · " + when : "Updated " + when);
		status.setForeground(prices.getError() != null ? STALE : MUTED);
	}

	// ------------------------------------------------------------------ flips

	private JPanel buildFlipsView()
	{
		JPanel view = new JPanel(new BorderLayout(0, 8));
		view.setOpaque(false);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(PANEL_WIDTH - 20, 30));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				rebuildFlips();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				rebuildFlips();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				rebuildFlips();
			}
		});
		search.addClearListener(this::rebuildFlips);

		filterSummary.setFont(FontManager.getRunescapeSmallFont());
		filterSummary.setForeground(MUTED);

		JPanel top = new JPanel(new BorderLayout(0, 6));
		top.setOpaque(false);
		top.add(search, BorderLayout.NORTH);
		top.add(filterSummary, BorderLayout.CENTER);

		flipList.setOpaque(false);
		view.add(top, BorderLayout.NORTH);
		view.add(flipList, BorderLayout.CENTER);
		return view;
	}

	private FlipFinder.Filter filter()
	{
		FlipFinder.Filter f = new FlipFinder.Filter();
		f.cash = Format.parseGp(config.cashStack());
		f.minVolume = config.minVolume();
		f.maxAgeSeconds = config.maxAgeMinutes() * 60L;
		f.members = config.members();
		f.sort = config.sort();
		f.search = search.getText();
		return f;
	}

	void rebuildFlips()
	{
		PriceService prices = plugin.getPrices();
		FlipFinder.Filter f = filter();
		filterSummary.setText(html((f.cash > 0 ? "Cash " + Format.gp(f.cash) : "Any cash")
			+ " · volume ≥ " + Format.gp(f.minVolume)
			+ " · ≤ " + config.maxAgeMinutes() + "m old"
			+ " · by " + f.sort.toString().toLowerCase()
			+ ". Change these in the plugin settings."));

		flipList.removeAll();
		if (prices.getUpdatedAt() == 0)
		{
			flipList.add(note(prices.getError() != null ? prices.getError() + ". Retrying every minute." : "Loading prices…"));
		}
		else
		{
			long now = Instant.now().getEpochSecond();
			List<FlipFinder.Flip> flips = FlipFinder.rank(prices.getItems().values(), prices.getLatest(), prices.getDay(), f, now);
			if (flips.isEmpty())
			{
				flipList.add(note("Nothing matches. Try a lower minimum volume, older prices or a bigger cash stack."));
			}
			for (FlipFinder.Flip flip : flips.subList(0, Math.min(flips.size(), config.rows())))
			{
				flipList.add(flipRow(flip));
			}
		}
		flipList.revalidate();
		flipList.repaint();
	}

	private JPanel flipRow(FlipFinder.Flip f)
	{
		String prices = "Buy " + Format.gp(f.buy) + " → " + Format.gp(f.sell);
		String gain = Format.signed(f.margin) + " (" + Format.percent(f.roi) + ") · " + Format.signed(f.profit) + "/limit";
		String tip = "<html><b>" + escape(f.item.name) + "</b><br>"
			+ "Buy at " + Format.exact(f.buy) + " (instant-sell price)<br>"
			+ "Sell at " + Format.exact(f.sell) + " (instant-buy price)<br>"
			+ "GE tax " + Format.exact(f.tax) + "<br>"
			+ "Margin " + Format.signed(f.margin) + " each, ROI " + Format.percent(f.roi) + "<br>"
			+ "Buy limit " + (f.item.limit == null ? "unknown" : Format.exact(f.item.limit))
			+ " · this flip: " + Format.exact(f.quantity) + "<br>"
			+ "Profit per limit " + Format.signed(f.profit) + "<br>"
			+ "24h volume " + Format.exact(f.volume) + "<br>"
			+ "Prices updated " + Format.ago(f.ageSeconds) + "<br><br>"
			+ "Click for the price chart. Right-click for more.</html>";
		JPanel row = itemRow(f.item.id, f.item.name, prices, f.ageSeconds > 1800 ? STALE : MUTED, gain, color(f.margin), tip);
		addMenu(row, f.item.id, f.item.name, null);
		return row;
	}

	// ------------------------------------------------------------------ my flips

	private JPanel buildLedgerView()
	{
		ledgerView.setOpaque(false);
		ledgerView.setLayout(new BoxLayout(ledgerView, BoxLayout.Y_AXIS));
		return ledgerView;
	}

	private void rebuildLedger()
	{
		FlipLedger ledger = plugin.getLedger();
		PriceService prices = plugin.getPrices();
		ledgerView.removeAll();

		long today = LocalDate.now().atStartOfDay(ZoneId.systemDefault()).toEpochSecond();
		long week = Instant.now().getEpochSecond() - 7 * 86400L;
		JPanel stats = new JPanel(new GridLayout(0, 2, 4, 4));
		stats.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		stats.setBorder(new EmptyBorder(8, 8, 8, 8));
		stat(stats, "Today", ledger.profitSince(today), ledger.salesSince(today));
		stat(stats, "Last 7 days", ledger.profitSince(week), ledger.salesSince(week));
		stat(stats, "All time", ledger.profitSince(0), ledger.salesSince(0));
		stack(ledgerView, stats);

		List<FlipLedger.Holding> holdings = ledger.holdings();
		List<FlipLedger.Sale> sales = ledger.recentSales(RECENT_SALES);

		if (holdings.isEmpty() && sales.isEmpty())
		{
			stack(ledgerView, note("Your flips appear here. Trade on the GE with RuneLite open: buys are "
				+ "remembered, and when you sell, the profit after tax is logged."));
		}

		if (!holdings.isEmpty())
		{
			stack(ledgerView, heading("Bought, not yet sold"));
			for (FlipLedger.Holding h : holdings)
			{
				Latest now = prices.getLatest().get(h.itemId);
				String line3;
				Color c3 = MUTED;
				if (now != null && now.high != null && now.high > 0)
				{
					long each = now.high - GeTax.perItem(now.high, h.itemId) - h.averageCost();
					line3 = "Sells now at " + Format.gp(now.high) + " · " + Format.signed(each * h.quantity);
					c3 = color(each);
				}
				else
				{
					line3 = "No current price";
				}
				JPanel row = itemRow(h.itemId, prices.name(h.itemId),
					Format.exact(h.quantity) + " × " + Format.gp(h.averageCost()) + " each", MUTED,
					line3, c3,
					"<html>Bought " + Format.exact(h.quantity) + " for " + Format.exact(h.cost) + " gp.<br>"
						+ "Profit shown is if sold now at the instant-buy price, after tax.<br><br>"
						+ "Right-click to stop tracking these (e.g. if you used them).</html>");
				addMenu(row, h.itemId, prices.name(h.itemId), () -> plugin.dropHolding(h.itemId));
				stack(ledgerView, row);
			}
		}

		if (!sales.isEmpty())
		{
			stack(ledgerView, heading("Recent sales"));
			long now = Instant.now().getEpochSecond();
			for (FlipLedger.Sale s : sales)
			{
				JPanel row = itemRow(s.itemId, prices.name(s.itemId),
					Format.exact(s.quantity) + " sold · " + Format.ago(now - s.time), MUTED,
					Format.signed(s.profit) + " gp", color(s.profit),
					"<html>Bought for " + Format.exact(s.cost) + "<br>"
						+ "Sold for " + Format.exact(s.revenue) + "<br>"
						+ "GE tax " + Format.exact(s.tax) + "<br>"
						+ "Profit " + Format.signed(s.profit) + "</html>");
				addMenu(row, s.itemId, prices.name(s.itemId), null);
				stack(ledgerView, row);
			}
		}

		if (!holdings.isEmpty() || !sales.isEmpty())
		{
			JButton clear = new JButton("Clear history");
			clear.setFont(FontManager.getRunescapeSmallFont());
			clear.setFocusPainted(false);
			clear.addActionListener(e ->
			{
				int answer = JOptionPane.showConfirmDialog(this,
					"Forget every recorded buy and sale for this account?",
					"GE Flipper", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
				if (answer == JOptionPane.OK_OPTION)
				{
					plugin.clearLedger();
					rebuildLedger();
				}
			});
			JPanel wrap = new JPanel(new BorderLayout());
			wrap.setOpaque(false);
			wrap.setBorder(new EmptyBorder(10, 0, 0, 0));
			wrap.add(clear, BorderLayout.CENTER);
			stack(ledgerView, wrap);
		}

		ledgerView.revalidate();
		ledgerView.repaint();
	}

	private static void stat(JPanel grid, String label, long profit, int count)
	{
		JLabel l = new JLabel(label + (count > 0 ? " (" + count + ")" : ""));
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(MUTED);
		JLabel v = new JLabel(Format.signed(profit), SwingConstants.RIGHT);
		v.setFont(FontManager.getRunescapeSmallFont());
		v.setForeground(profit == 0 ? Color.WHITE : color(profit));
		grid.add(l);
		grid.add(v);
	}

	// ------------------------------------------------------------------ building blocks

	/** A row with the item icon and three lines of text. */
	private JPanel itemRow(int itemId, String name, String line2, Color c2, String line3, Color c3, String tooltip)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(5, 6, 5, 6));
		row.setToolTipText(tooltip);

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(itemId).addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel(new GridLayout(3, 1));
		text.setOpaque(false);
		text.add(label(name, Color.WHITE));
		text.add(label(line2, c2));
		text.add(label(line3, c3));
		row.add(text, BorderLayout.CENTER);

		// Right-clicking anywhere on the row opens the row's menu.
		icon.setInheritsPopupMenu(true);
		text.setInheritsPopupMenu(true);
		for (java.awt.Component c : text.getComponents())
		{
			((JLabel) c).setInheritsPopupMenu(true);
		}

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		return row;
	}

	/** Left click opens the wiki price chart; right click offers more. */
	private void addMenu(JPanel row, int itemId, String name, Runnable stopTracking)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem chart = new JMenuItem("Open price chart");
		chart.addActionListener(e -> LinkBrowser.browse(priceUrl(itemId)));
		JMenuItem wiki = new JMenuItem("Open wiki page");
		wiki.addActionListener(e -> LinkBrowser.browse("https://oldschool.runescape.wiki/w/Special:Lookup?type=item&id=" + itemId));
		menu.add(chart);
		menu.add(wiki);
		if (stopTracking != null)
		{
			JMenuItem stop = new JMenuItem("Stop tracking " + name);
			stop.addActionListener(e ->
			{
				stopTracking.run();
				rebuildLedger();
			});
			menu.add(stop);
		}
		row.setComponentPopupMenu(menu);
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (e.getButton() == MouseEvent.BUTTON1)
				{
					LinkBrowser.browse(priceUrl(itemId));
				}
			}
		});
	}

	private static String priceUrl(int itemId)
	{
		return "https://prices.runescape.wiki/osrs/item/" + itemId;
	}

	private static JLabel label(String text, Color color)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	private static JLabel heading(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(new EmptyBorder(12, 0, 6, 0));
		return l;
	}

	private static JLabel note(String text)
	{
		JLabel l = new JLabel(html(text));
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(MUTED);
		l.setBorder(BorderFactory.createEmptyBorder(8, 0, 8, 0));
		return l;
	}

	/** Stack components in the ledger view with a small gap, full width. */
	private static void stack(JPanel column, javax.swing.JComponent c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		column.add(c);
		if (c instanceof JPanel && ((JPanel) c).getBackground() == ColorScheme.DARKER_GRAY_COLOR)
		{
			JPanel gap = new JPanel();
			gap.setOpaque(false);
			gap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 4));
			gap.setPreferredSize(new Dimension(0, 4));
			column.add(gap);
		}
	}

	private static Color color(long n)
	{
		return n > 0 ? GAIN : n < 0 ? LOSS : MUTED;
	}

	/** Wrap text to the panel width. */
	private static String html(String text)
	{
		return "<html><body style='width:" + (PANEL_WIDTH - 30) + "px'>" + escape(text) + "</body></html>";
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.geflipper;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.lang.reflect.Type;
import java.time.Instant;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "GE Flipper",
	description = "Live Grand Exchange flips with margins after tax, and a profit log of your own flips",
	tags = {"grand", "exchange", "flip", "flipping", "merch", "margin", "prices", "money", "profit"}
)
public class GeFlipperPlugin extends Plugin
{
	private static final String LEDGER_KEY = "ledger";
	private static final String SLOTS_KEY = "slots";
	/** Ticks after login or a world hop during which the client replays offers. */
	private static final int LOGIN_BURST_TICKS = 2;
	private static final Type SLOTS_TYPE = new TypeToken<Map<Integer, OfferTracker.Snapshot>>()
	{
	}.getType();

	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private GeFlipperConfig config;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	@Getter
	private PriceService prices;

	@Getter
	private FlipLedger ledger = new FlipLedger();
	private OfferTracker tracker = new OfferTracker();

	private GeFlipperPanel panel;
	private NavigationButton navButton;
	private ScheduledFuture<?> refreshTask;
	private int lastLoginTick = -1;

	@Provides
	GeFlipperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeFlipperConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new GeFlipperPanel(this, config, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("GE Flipper")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		loadProfile();
		refreshTask = executor.scheduleAtFixedRate(
			() -> prices.refresh(() -> SwingUtilities.invokeLater(panel::pricesUpdated)),
			0, 60, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
		clientToolbar.removeNavigation(navButton);
		panel.dispose();
		panel = null;
		navButton = null;
	}

	/** Refresh now, from the panel's button. */
	void refreshNow()
	{
		executor.execute(() -> prices.refresh(() -> SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.pricesUpdated();
			}
		})));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GeFlipperConfig.GROUP.equals(event.getGroup()) && panel != null
			&& !LEDGER_KEY.equals(event.getKey()) && !SLOTS_KEY.equals(event.getKey()))
		{
			SwingUtilities.invokeLater(panel::rebuildFlips);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadProfile();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			lastLoginTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		GrandExchangeOffer offer = event.getOffer();
		GrandExchangeOfferState state = offer.getState();
		int slot = event.getSlot();

		// The client empties every slot while logging in or hopping; those are not real.
		if (state == GrandExchangeOfferState.EMPTY)
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				tracker.clear(slot);
				saveSlots();
			}
			return;
		}

		boolean buy = state == GrandExchangeOfferState.BUYING
			|| state == GrandExchangeOfferState.BOUGHT
			|| state == GrandExchangeOfferState.CANCELLED_BUY;
		boolean live = client.getGameState() == GameState.LOGGED_IN
			&& client.getTickCount() > lastLoginTick + LOGIN_BURST_TICKS;

		OfferTracker.Fill fill = tracker.update(slot, offer.getItemId(), buy, offer.getPrice(),
			offer.getTotalQuantity(), offer.getQuantitySold(), offer.getSpent(), live);
		saveSlots();
		if (fill == null)
		{
			return;
		}

		long now = Instant.now().getEpochSecond();
		if (fill.buy)
		{
			ledger.recordBuy(fill.itemId, fill.quantity, fill.gp, now);
		}
		else
		{
			FlipLedger.Sale sale = ledger.recordSell(fill.itemId, fill.quantity, fill.gp, now);
			if (sale != null && config.chatMessages())
			{
				announce(sale);
			}
		}
		saveLedger();
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.ledgerUpdated();
			}
		});
	}

	private void announce(FlipLedger.Sale sale)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.NORMAL)
			.append("GE Flipper: sold " + Format.exact(sale.quantity) + " x " + prices.name(sale.itemId) + " for ")
			.append(ChatColorType.HIGHLIGHT)
			.append(Format.signed(sale.profit) + " gp")
			.append(ChatColorType.NORMAL)
			.append(" profit after tax.")
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}

	/** Forget all recorded flips for this account. */
	void clearLedger()
	{
		ledger.clear();
		saveLedger();
	}

	void dropHolding(int itemId)
	{
		ledger.dropHolding(itemId);
		saveLedger();
	}

	// ------------------------------------------------------------------ persistence

	/** Flips and slot snapshots are stored per account, in the RuneScape profile. */
	private void loadProfile()
	{
		ledger = read(LEDGER_KEY, FlipLedger.class, new FlipLedger());
		tracker = new OfferTracker();
		tracker.setSlots(read(SLOTS_KEY, SLOTS_TYPE, null));
		if (panel != null)
		{
			SwingUtilities.invokeLater(panel::ledgerUpdated);
		}
	}

	private <T> T read(String key, Type type, T fallback)
	{
		String json = configManager.getRSProfileConfiguration(GeFlipperConfig.GROUP, key);
		if (json == null || json.isEmpty())
		{
			return fallback;
		}
		try
		{
			T value = gson.fromJson(json, type);
			return value != null ? value : fallback;
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Unreadable GE Flipper {} data, starting fresh", key, e);
			return fallback;
		}
	}

	private void saveLedger()
	{
		String json;
		synchronized (ledger)
		{
			json = gson.toJson(ledger);
		}
		configManager.setRSProfileConfiguration(GeFlipperConfig.GROUP, LEDGER_KEY, json);
	}

	private void saveSlots()
	{
		configManager.setRSProfileConfiguration(GeFlipperConfig.GROUP, SLOTS_KEY, gson.toJson(tracker.getSlots(), SLOTS_TYPE));
	}
}

package com.geflipper;

import java.util.Set;

/**
 * The Grand Exchange tax: 2% of the sale price per item, rounded down and
 * capped at 5M, since 29 May 2025. Items selling for under 50 gp round to
 * zero, and the bond and a handful of low-level tools are exempt.
 */
public final class GeTax
{
	public static final double RATE = 0.02;
	public static final long CAP = 5_000_000L;

	static final Set<Integer> EXEMPT = Set.of(
		13190, // Old school bond
		1755, // Chisel
		5325, // Gardening trowel
		1785, // Glassblowing pipe
		2347, // Hammer
		1733, // Needle
		233, // Pestle and mortar
		5341, // Rake
		8794, // Saw
		5329, // Secateurs
		5343, // Seed dibber
		1735, // Shears
		952, // Spade
		5331 // Watering can
	);

	private GeTax()
	{
	}

	/** Tax on selling one of {@code itemId} at {@code price}. */
	public static long perItem(long price, int itemId)
	{
		if (price <= 0 || EXEMPT.contains(itemId))
		{
			return 0;
		}
		return Math.min((long) Math.floor(price * RATE), CAP);
	}
}

package com.geflipper;

import java.util.HashMap;
import java.util.Map;

/**
 * Turns the client's GE offer updates into fills: "you just bought 40 more
 * yew logs for 9,200 gp".
 *
 * The client reports each slot's running totals (items traded so far, gp
 * spent or received so far), and replays every slot on login. A fill is the
 * difference from the last snapshot of the same offer, so replays and
 * repeated events never count twice. A slot seen for the first time is
 * taken as a baseline, since there is no way to know how much of it was
 * traded before we were watching.
 */
public final class OfferTracker
{
	/** What we last saw in one GE slot. */
	public static final class Snapshot
	{
		public int itemId;
		public boolean buy;
		public long price;
		public int total;
		public int traded;
		public long spent;

		boolean sameOffer(int itemId, boolean buy, long price, int total)
		{
			return this.itemId == itemId && this.buy == buy && this.price == price && this.total == total;
		}
	}

	/** Items traded since the last update of a slot. */
	public static final class Fill
	{
		public final int itemId;
		public final boolean buy;
		public final int quantity;
		/** gp paid (buy) or received before tax (sell) for these items. */
		public final long gp;

		Fill(int itemId, boolean buy, int quantity, long gp)
		{
			this.itemId = itemId;
			this.buy = buy;
			this.quantity = quantity;
			this.gp = gp;
		}
	}

	private Map<Integer, Snapshot> slots = new HashMap<>();

	public Map<Integer, Snapshot> getSlots()
	{
		return slots;
	}

	public void setSlots(Map<Integer, Snapshot> slots)
	{
		this.slots = slots == null ? new HashMap<>() : new HashMap<>(slots);
	}

	/**
	 * The slot was collected and is empty again. It is remembered as empty
	 * rather than forgotten, so the next offer placed in it is known to be
	 * new rather than one we never saw start.
	 */
	public void clear(int slot)
	{
		slots.put(slot, new Snapshot());
	}

	/**
	 * Record a slot's current totals.
	 *
	 * @param live false during the burst of updates the client sends on
	 *             login or world hop, when a new-looking offer may be one
	 *             that filled while we were away
	 * @return the fill since the last update, or null if nothing new traded
	 */
	public Fill update(int slot, int itemId, boolean buy, long price, int total, int traded, long spent, boolean live)
	{
		Snapshot prev = slots.get(slot);
		Snapshot now = new Snapshot();
		now.itemId = itemId;
		now.buy = buy;
		now.price = price;
		now.total = total;
		now.traded = traded;
		now.spent = spent;
		slots.put(slot, now);

		if (prev == null)
		{
			// A slot we have never seen: its trades so far are history.
			return null;
		}
		if (!prev.sameOffer(itemId, buy, price, total))
		{
			// A new offer in a slot we watched empty. If we are live, whatever
			// has traded happened just now; otherwise it filled while we were
			// logged out, and we cannot tell how much was already counted.
			return live && traded > 0 && spent > 0 ? new Fill(itemId, buy, traded, spent) : null;
		}

		int dq = traded - prev.traded;
		long dgp = spent - prev.spent;
		if (dq <= 0 || dgp <= 0)
		{
			return null;
		}
		return new Fill(itemId, buy, dq, dgp);
	}
}

package com.geflipper;

import java.util.Collections;
import java.util.Map;

/**
 * The shapes of the OSRS Wiki real-time prices API responses, for Gson.
 * Field names match the JSON.
 */
public final class PriceData
{
	private PriceData()
	{
	}

	/** One entry of /mapping. */
	public static final class ItemInfo
	{
		public int id;
		public String name = "";
		public String examine = "";
		public boolean members;
		/** Four-hour buy limit; null when the wiki does not know it. */
		public Integer limit;
		public Integer highalch;
		public String icon;
	}

	/**
	 * One entry of /latest. {@code high} is the latest instant-buy price and
	 * {@code low} the latest instant-sell price; times are unix seconds.
	 */
	public static final class Latest
	{
		public Long high;
		public Long highTime;
		public Long low;
		public Long lowTime;
	}

	/** One entry of /1h or /24h. */
	public static final class Average
	{
		public Long avgHighPrice;
		public long highPriceVolume;
		public Long avgLowPrice;
		public long lowPriceVolume;

		public long volume()
		{
			return highPriceVolume + lowPriceVolume;
		}
	}

	public static final class LatestResponse
	{
		public Map<Integer, Latest> data = Collections.emptyMap();
	}

	public static final class AverageResponse
	{
		public Map<Integer, Average> data = Collections.emptyMap();
	}
}

package com.geflipper;

import com.geflipper.PriceData.Average;
import com.geflipper.PriceData.AverageResponse;
import com.geflipper.PriceData.ItemInfo;
import com.geflipper.PriceData.Latest;
import com.geflipper.PriceData.LatestResponse;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Keeps prices from the OSRS Wiki real-time prices API. The item list is
 * fetched once, the latest prices on every refresh, and the day's volumes
 * every five minutes, as the wiki asks tools not to poll faster than the data
 * changes. All requests are asynchronous.
 */
@Slf4j
@Singleton
public class PriceService
{
	static final String API = "https://prices.runescape.wiki/api/v1/osrs";
	static final String USER_AGENT = "GE Flipper RuneLite plugin - github.com/Ratbag24/RuneScape-";
	private static final long AVERAGES_EVERY_MS = 5 * 60_000;
	private static final Type MAPPING_TYPE = new TypeToken<List<ItemInfo>>()
	{
	}.getType();

	private final OkHttpClient http;
	private final Gson gson;

	@Getter
	private volatile Map<Integer, ItemInfo> items = Collections.emptyMap();
	@Getter
	private volatile Map<Integer, Latest> latest = Collections.emptyMap();
	@Getter
	private volatile Map<Integer, Average> day = Collections.emptyMap();
	/** When prices last arrived, in epoch millis; 0 before the first. */
	@Getter
	private volatile long updatedAt;
	/** The last refresh's error, or null if it worked. */
	@Getter
	private volatile String error;

	private long averagesAt;
	private boolean inFlight;

	@Inject
	PriceService(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	public String name(int itemId)
	{
		ItemInfo info = items.get(itemId);
		return info != null ? info.name : "Item " + itemId;
	}

	/** Fetch what is due, then run {@code done} (on an OkHttp thread). */
	public synchronized void refresh(Runnable done)
	{
		if (inFlight)
		{
			return;
		}
		inFlight = true;
		boolean wantAverages = System.currentTimeMillis() - averagesAt > AVERAGES_EVERY_MS;

		CompletableFuture<Map<Integer, ItemInfo>> mapping = items.isEmpty()
			? this.<List<ItemInfo>>get("/mapping", MAPPING_TYPE).thenApply(PriceService::byId)
			: CompletableFuture.completedFuture(items);
		CompletableFuture<Map<Integer, Latest>> prices = this.<LatestResponse>get("/latest", LatestResponse.class)
			.thenApply(r -> r.data);
		CompletableFuture<Map<Integer, Average>> volumes = wantAverages
			? this.<AverageResponse>get("/24h", AverageResponse.class)
			.thenApply(r -> r.data)
			// If the daily endpoint fails, estimate a day from the last hour.
			.exceptionally(e -> null)
			.thenCompose(d -> d != null && !d.isEmpty()
				? CompletableFuture.completedFuture(d)
				: this.<AverageResponse>get("/1h", AverageResponse.class).thenApply(r -> scale(r.data, 24)))
			: CompletableFuture.completedFuture(null);

		CompletableFuture.allOf(mapping, prices, volumes).whenComplete((ok, err) ->
		{
			synchronized (this)
			{
				inFlight = false;
				if (err != null)
				{
					log.debug("Price refresh failed", err);
					error = "Can't reach the wiki price API";
				}
				else
				{
					items = mapping.join();
					latest = prices.join();
					Map<Integer, Average> v = volumes.join();
					if (v != null)
					{
						day = v;
						averagesAt = System.currentTimeMillis();
					}
					updatedAt = System.currentTimeMillis();
					error = null;
				}
			}
			done.run();
		});
	}

	private <T> CompletableFuture<T> get(String path, Type type)
	{
		CompletableFuture<T> future = new CompletableFuture<>();
		Request request = new Request.Builder()
			.url(API + path)
			.header("User-Agent", USER_AGENT)
			.build();
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						throw new IOException(path + " returned " + response.code());
					}
					T parsed = gson.fromJson(body.charStream(), type);
					if (parsed == null)
					{
						throw new IOException(path + " returned nothing");
					}
					future.complete(parsed);
				}
				catch (Exception e)
				{
					future.completeExceptionally(e);
				}
			}
		});
		return future;
	}

	private static Map<Integer, ItemInfo> byId(List<ItemInfo> list)
	{
		Map<Integer, ItemInfo> map = new LinkedHashMap<>();
		for (ItemInfo i : list)
		{
			if (i != null && i.name != null)
			{
				map.put(i.id, i);
			}
		}
		return Collections.unmodifiableMap(map);
	}

	private static Map<Integer, Average> scale(Map<Integer, Average> hour, int factor)
	{
		Map<Integer, Average> out = new HashMap<>();
		for (Map.Entry<Integer, Average> e : hour.entrySet())
		{
			Average a = new Average();
			a.avgHighPrice = e.getValue().avgHighPrice;
			a.avgLowPrice = e.getValue().avgLowPrice;
			a.highPriceVolume = e.getValue().highPriceVolume * factor;
			a.lowPriceVolume = e.getValue().lowPriceVolume * factor;
			out.put(e.getKey(), a);
		}
		return out;
	}
}

package com.geflipper;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.geflipper.PriceData.Average;
import com.geflipper.PriceData.ItemInfo;
import com.geflipper.PriceData.Latest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** Tests for the parts with no RuneLite dependency: tax, flips, offers, ledger. */
public class CoreTest
{
	private static final long NOW = 1_800_000_000L;

	// ------------------------------------------------------------------ tax

	@Test
	public void taxIsTwoPercentRoundedDown()
	{
		assertEquals(20, GeTax.perItem(1000, 1));
		assertEquals(20, GeTax.perItem(1049, 1));
		assertEquals(21, GeTax.perItem(1050, 1));
	}

	@Test
	public void taxIsZeroUnderFiftyGp()
	{
		assertEquals(0, GeTax.perItem(49, 1));
		assertEquals(1, GeTax.perItem(50, 1));
	}

	@Test
	public void taxCapsAtFiveMillion()
	{
		assertEquals(5_000_000, GeTax.perItem(1_450_000_000L, 20997));
		assertEquals(4_999_999, GeTax.perItem(249_999_999L, 1));
	}

	@Test
	public void bondAndToolsAreExempt()
	{
		assertEquals(0, GeTax.perItem(8_500_000, 13190));
		assertEquals(0, GeTax.perItem(1000, 1755));
	}

	// ------------------------------------------------------------------ flips

	private static ItemInfo item(int id, String name, boolean members, Integer limit)
	{
		ItemInfo i = new ItemInfo();
		i.id = id;
		i.name = name;
		i.members = members;
		i.limit = limit;
		return i;
	}

	private static Latest price(long high, long low, long age)
	{
		Latest p = new Latest();
		p.high = high;
		p.low = low;
		p.highTime = NOW - age;
		p.lowTime = NOW - age;
		return p;
	}

	private static Average volume(long v)
	{
		Average a = new Average();
		a.highPriceVolume = v / 2;
		a.lowPriceVolume = v - v / 2;
		return a;
	}

	@Test
	public void marginIsSellMinusTaxMinusBuy()
	{
		FlipFinder.Flip f = FlipFinder.flip(item(4151, "Abyssal whip", true, 70), price(1_560_000, 1_540_000, 60), volume(6000), 0, NOW);
		assertEquals(31_200, f.tax);
		assertEquals(-11_200, f.margin);
		assertEquals(70, f.quantity);
	}

	@Test
	public void flipNeedsBothPrices()
	{
		Latest p = price(100, 90, 0);
		p.low = null;
		assertNull(FlipFinder.flip(item(1, "A", false, 10), p, null, 0, NOW));
	}

	@Test
	public void quantityIsBoundedByLimitAndCash()
	{
		assertEquals(70, FlipFinder.quantity(70, 1000, 0));
		assertEquals(20, FlipFinder.quantity(70, 1000, 20_000));
		assertEquals(20, FlipFinder.quantity(null, 1000, 20_000));
		assertEquals(0, FlipFinder.quantity(null, 1000, 0));
	}

	@Test
	public void rankFiltersAndSortsByProfit()
	{
		List<ItemInfo> items = new ArrayList<>();
		Map<Integer, Latest> latest = new HashMap<>();
		Map<Integer, Average> day = new HashMap<>();
		items.add(item(1, "A", false, 100));
		latest.put(1, price(1200, 1000, 60)); // margin 176 (17.6%), profit 17,600
		items.add(item(2, "B", false, 10_000));
		latest.put(2, price(220, 200, 60)); // margin 16 (8%), profit 160,000
		items.add(item(3, "C", false, 100));
		latest.put(3, price(1000, 1000, 60)); // loses the tax
		items.add(item(4, "D", false, 100));
		latest.put(4, price(500, 400, 60)); // too thin
		items.add(item(5, "E", true, 100));
		latest.put(5, price(500, 400, 7200)); // stale
		for (int id = 1; id <= 5; id++)
		{
			day.put(id, volume(id == 4 ? 10 : 5000));
		}

		FlipFinder.Filter filter = new FlipFinder.Filter();
		List<FlipFinder.Flip> flips = FlipFinder.rank(items, latest, day, filter, NOW);
		assertEquals(2, flips.size());
		assertEquals("B", flips.get(0).item.name);
		assertEquals(160_000, flips.get(0).profit);
		assertEquals("A", flips.get(1).item.name);

		filter.sort = FlipFinder.Sort.ROI;
		assertEquals("A", FlipFinder.rank(items, latest, day, filter, NOW).get(0).item.name);

		filter.cash = 150_000;
		filter.sort = FlipFinder.Sort.PROFIT;
		List<FlipFinder.Flip> withCash = FlipFinder.rank(items, latest, day, filter, NOW);
		// 150K buys all 100 of A's limit but only 750 of B's 10,000.
		assertEquals("A", withCash.get(0).item.name);
		assertEquals(100, withCash.get(0).quantity);
		assertEquals(750, withCash.get(1).quantity);
		assertEquals(12_000, withCash.get(1).profit);

		filter.search = "a";
		assertEquals(1, FlipFinder.rank(items, latest, day, filter, NOW).size());
	}

	// ------------------------------------------------------------------ offers

	@Test
	public void offerFillsAreDifferences()
	{
		OfferTracker t = new OfferTracker();
		t.clear(0); // slot seen empty
		assertNull(t.update(0, 1515, true, 230, 1000, 0, 0, true));
		OfferTracker.Fill f = t.update(0, 1515, true, 230, 1000, 400, 91_000, true);
		assertEquals(400, f.quantity);
		assertEquals(91_000, f.gp);
		f = t.update(0, 1515, true, 230, 1000, 1000, 228_000, true);
		assertEquals(600, f.quantity);
		assertEquals(137_000, f.gp);
		// The same totals again (e.g. BUYING then BOUGHT, or a login replay).
		assertNull(t.update(0, 1515, true, 230, 1000, 1000, 228_000, false));
	}

	@Test
	public void unseenSlotIsABaseline()
	{
		OfferTracker t = new OfferTracker();
		assertNull(t.update(3, 1515, true, 230, 1000, 400, 91_000, true));
		OfferTracker.Fill f = t.update(3, 1515, true, 230, 1000, 500, 114_000, true);
		assertEquals(100, f.quantity);
	}

	@Test
	public void offlineFillsCountOnLogin()
	{
		OfferTracker t = new OfferTracker();
		t.clear(1);
		t.update(1, 453, false, 150, 5000, 0, 0, true);
		// Logged out; the rest sold; the login replay reports the new totals.
		OfferTracker.Fill f = t.update(1, 453, false, 150, 5000, 5000, 760_000, false);
		assertNotNull(f);
		assertEquals(5000, f.quantity);
		assertTrue(!f.buy);
	}

	@Test
	public void newOfferDuringLoginIsNotCounted()
	{
		OfferTracker t = new OfferTracker();
		t.clear(2);
		// Placed and filled on another device: we cannot know what we missed.
		assertNull(t.update(2, 561, true, 95, 1000, 1000, 95_000, false));
		// Placed and instantly filled while we watch: counted.
		t.clear(2);
		assertEquals(1000, t.update(2, 561, true, 95, 1000, 1000, 95_000, true).quantity);
	}

	// ------------------------------------------------------------------ ledger

	@Test
	public void saleProfitIsAfterTax()
	{
		FlipLedger l = new FlipLedger();
		l.recordBuy(1515, 1000, 228_000, NOW);
		FlipLedger.Sale s = l.recordSell(1515, 1000, 240_000, NOW + 60);
		assertEquals(1000, s.quantity);
		assertEquals(228_000, s.cost);
		assertEquals(4 * 1000, s.tax); // 240 gp each -> 4 gp tax each
		assertEquals(240_000 - 4000 - 228_000, s.profit);
		assertTrue(l.lots.isEmpty());
	}

	@Test
	public void salesMatchOldestLotsFirst()
	{
		FlipLedger l = new FlipLedger();
		l.recordBuy(2, 100, 10_000, NOW); // 100 each
		l.recordBuy(2, 100, 20_000, NOW + 1); // 200 each
		FlipLedger.Sale s = l.recordSell(2, 150, 45_000, NOW + 2); // 300 each
		assertEquals(10_000 + 10_000, s.cost);
		assertEquals(150 * 6, s.tax);
		assertEquals(45_000 - 900 - 20_000, s.profit);
		List<FlipLedger.Holding> h = l.holdings();
		assertEquals(1, h.size());
		assertEquals(50, h.get(0).quantity);
		assertEquals(200, h.get(0).averageCost());
	}

	@Test
	public void unmatchedSalesAreLeftOut()
	{
		FlipLedger l = new FlipLedger();
		assertNull(l.recordSell(2, 10, 3000, NOW));
		l.recordBuy(2, 5, 1000, NOW);
		FlipLedger.Sale s = l.recordSell(2, 10, 3000, NOW); // only 5 were bought
		assertEquals(5, s.quantity);
		assertEquals(1500, s.revenue);
		assertEquals(1500 - 30 - 1000, s.profit);
	}

	@Test
	public void profitSinceSumsRecentSales()
	{
		FlipLedger l = new FlipLedger();
		l.recordBuy(1, 10, 1000, NOW);
		l.recordSell(1, 5, 1000, NOW + 10);
		l.recordSell(1, 5, 1000, NOW + 100);
		assertEquals(2, l.salesSince(NOW));
		assertEquals(1, l.salesSince(NOW + 50));
		assertEquals(l.sales.get(1).profit, l.profitSince(NOW + 50));
	}

	@Test
	public void ledgerKeepsBoundedHistory()
	{
		FlipLedger l = new FlipLedger();
		for (int i = 0; i < FlipLedger.MAX_SALES + 20; i++)
		{
			l.recordBuy(1, 1, 100, NOW + i);
			l.recordSell(1, 1, 200, NOW + i);
		}
		assertEquals(FlipLedger.MAX_SALES, l.sales.size());
	}

	// ------------------------------------------------------------------ format

	@Test
	public void formatsGpLikeTheGe()
	{
		assertEquals("950", Format.gp(950));
		assertEquals("12,400", Format.gp(12_400));
		assertEquals("125K", Format.gp(125_000));
		assertEquals("1M", Format.gp(999_600));
		assertEquals("4.56M", Format.gp(4_560_000));
		assertEquals("125.3M", Format.gp(125_300_000));
		assertEquals("1.45B", Format.gp(1_450_000_000L));
		assertEquals("-340", Format.gp(-340));
		assertEquals("+1.2M", Format.signed(1_200_000));
		assertEquals("5.23%", Format.percent(0.0523));
	}

	@Test
	public void parsesTypedAmounts()
	{
		assertEquals(10_000_000, Format.parseGp("10m"));
		assertEquals(250_000, Format.parseGp("250K"));
		assertEquals(1_500_000_000L, Format.parseGp("1.5b"));
		assertEquals(12_000, Format.parseGp("12,000"));
		assertEquals(0, Format.parseGp(""));
		assertEquals(0, Format.parseGp("lots"));
	}
}

